DROP TABLE IF EXISTS FilmInList CASCADE;
DROP TABLE IF EXISTS UserFavoriteGenre CASCADE;
DROP TABLE IF EXISTS FilmGenre CASCADE;
DROP TABLE IF EXISTS Review CASCADE;
DROP TABLE IF EXISTS Film CASCADE;
DROP TABLE IF EXISTS FilmDirector CASCADE;
DROP TABLE IF EXISTS Genre CASCADE;
DROP TABLE IF EXISTS UserProfile CASCADE;
DROP TABLE IF EXISTS UserList CASCADE;
DROP TABLE IF EXISTS Comment CASCADE;

CREATE TABLE UserProfile (
    "id_user" INTEGER PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    "username" VARCHAR(255) NOT NULL UNIQUE,
    "password" VARCHAR(255) NOT NULL,
    "name" VARCHAR(255) NOT NULL,
    "birthday" DATE NOT NULL,
    "gender" VARCHAR(255) NOT NULL,
    "role" VARCHAR(50) NOT NULL CHECK (role IN ('user', 'moderator'))  -- роль 'user' или 'moderator'
);
CREATE TABLE Genre (
    "name_genre" VARCHAR(255) NOT NULL PRIMARY KEY
);
CREATE TABLE FilmDirector (
    "id_director" INTEGER PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    "name" VARCHAR(255) NOT NULL,
    "birthday" DATE NOT NULL,
    "gender" VARCHAR(255) NOT NULL
);
CREATE TABLE Film (
    "id_film" INTEGER PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    "id_director" INTEGER REFERENCES FilmDirector(id_director),
    "name" VARCHAR(255) NOT NULL,
    "description" TEXT NOT NULL,
    "actors" TEXT NOT NULL,
    "poster_path" VARCHAR(500) NOT NULL,
    "date" SMALLINT NOT NULL --использую smallint вместо date тк у многих фильмов только год, а не полная дата
);
CREATE TABLE Review (
    "id_review" INTEGER PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    "id_film" INTEGER REFERENCES Film(id_film) ON DELETE CASCADE,
    "id_reader" INTEGER REFERENCES UserProfile(id_user) ON DELETE CASCADE,
    "text_review" TEXT NOT NULL,
    "date_review" TIMESTAMP WITH TIME ZONE NOT NULL
);
CREATE TABLE UserList (
    "name" VARCHAR(255) NOT NULL,
    "id_watcher" INTEGER REFERENCES UserProfile(id_user) ON DELETE CASCADE,
    PRIMARY KEY(name, id_watcher)
);
CREATE TABLE FilmInList (
    "id_film" INTEGER REFERENCES Film(id_film) ON DELETE CASCADE,
    "name_list" VARCHAR(255) NOT NULL,
    "id_watcher" INTEGER NOT NULL REFERENCES UserProfile(id_user) ON DELETE CASCADE,
    PRIMARY KEY(id_film, name_list, id_watcher),
    FOREIGN KEY (name_list, id_watcher) REFERENCES UserList(name, id_watcher) ON DELETE CASCADE
);
CREATE TABLE FilmGenre (
    "name" VARCHAR(255) NOT NULL REFERENCES Genre(name_genre) ON DELETE CASCADE,
    "id_film" INTEGER REFERENCES Film(id_film) ON DELETE CASCADE,
    PRIMARY KEY(name, id_film)
);
CREATE TABLE UserFavoriteGenre (
    "id_watcher" INTEGER REFERENCES UserProfile(id_user) ON DELETE CASCADE,
    "name" VARCHAR(255) NOT NULL REFERENCES Genre(name_genre) ON DELETE CASCADE,
    PRIMARY KEY(name, id_watcher)
);
CREATE TABLE Comment (
    "id_comment" INTEGER PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    "date" TIMESTAMP WITH TIME ZONE NOT NULL,
    "id_user" INTEGER REFERENCES UserProfile(id_user) ON DELETE CASCADE,
    "comment_text" TEXT NOT NULL,
    "id_review" INTEGER REFERENCES Review(id_review) ON DELETE CASCADE
);

